// Differential checks of CaseHeuristics-pbo.js against Lean, generated by leanscript --check
import * as M from "./CaseHeuristics-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("testP(-7, -7, -7)", () => M.testP(-7, -7, -7), "5", false);
check("testP(-7, -1, -1)", () => M.testP(-7, -1, -1), "5", false);
check("testP(-1, -1, -7)", () => M.testP(-1, -1, -7), "5", false);
check("testP(-7, 0, 0)", () => M.testP(-7, 0, 0), "5", false);
check("testP(-1, 0, -1)", () => M.testP(-1, 0, -1), "5", false);
check("testP(0, 0, -7)", () => M.testP(0, 0, -7), "5", false);
check("testP(-7, 3, 3)", () => M.testP(-7, 3, 3), "5", false);
check("testP(-1, 3, 0)", () => M.testP(-1, 3, 0), "5", false);
check("testP(0, -7, 12)", () => M.testP(0, -7, 12), "5", false);
check("testP(0, 3, -1)", () => M.testP(0, 3, -1), "5", false);
check("testP(3, -7, 3)", () => M.testP(3, -7, 3), "5", false);
check("testP(3, 3, -7)", () => M.testP(3, 3, -7), "5", false);
check("testP(12, -7, 0)", () => M.testP(12, -7, 0), "5", false);
check("testP(-7, 12, 12)", () => M.testP(-7, 12, 12), "5", false);
check("testP(-1, 12, 3)", () => M.testP(-1, 12, 3), "5", false);
check("testP(0, 12, 0)", () => M.testP(0, 12, 0), "5", false);
check("testP(3, -1, 12)", () => M.testP(3, -1, 12), "5", false);
check("testP(3, 12, -1)", () => M.testP(3, 12, -1), "5", false);
check("testP(12, -1, 3)", () => M.testP(12, -1, 3), "5", false);
check("testP(12, 12, -7)", () => M.testP(12, 12, -7), "5", false);
check("testP(12, 0, 12)", () => M.testP(12, 0, 12), "5", false);

console.log(`CaseHeuristics-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
